    process.exit(1);
  }

  try {
    parentPort.postMessage('hello');
  } catch (postError: unknown) {
    process.stderr.write(`failed to post message from worker: ${formatErrorMessage(postError)}\n`);
    process.exit(1);
  }
}

// Entry point execution
if (isMainThread) {
  void runMainThread();
} else {
  runWorkerThread();
}

